CREATE TYPE stock_transaction_type AS ENUM('PURCHASE','DISPENSE','ADJUSTMENT','RETURN','EXPIRED');
CREATE TABLE medicine_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),medicine_id uuid NOT NULL REFERENCES medicines(id) ON DELETE RESTRICT,batch_number text NOT NULL,expiry_date date NOT NULL,quantity integer NOT NULL DEFAULT 0,purchase_price numeric(14,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT medicine_batches_quantity_check CHECK(quantity>=0));CREATE UNIQUE INDEX medicine_batches_number_uidx ON medicine_batches(medicine_id,batch_number);CREATE INDEX medicine_batches_fefo_idx ON medicine_batches(medicine_id,expiry_date);
CREATE TABLE stock_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),medicine_id uuid NOT NULL REFERENCES medicines(id) ON DELETE RESTRICT,batch_id uuid NOT NULL REFERENCES medicine_batches(id) ON DELETE RESTRICT,type stock_transaction_type NOT NULL,quantity integer NOT NULL,reference text,created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT stock_transactions_nonzero_check CHECK(quantity<>0));CREATE INDEX stock_transactions_medicine_idx ON stock_transactions(medicine_id);CREATE INDEX stock_transactions_batch_idx ON stock_transactions(batch_id);CREATE INDEX stock_transactions_created_idx ON stock_transactions(created_at);
CREATE TABLE dispense_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),prescription_item_id uuid NOT NULL REFERENCES prescription_items(id) ON DELETE RESTRICT,batch_id uuid NOT NULL REFERENCES medicine_batches(id) ON DELETE RESTRICT,quantity integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT dispense_allocations_quantity_check CHECK(quantity>0));CREATE UNIQUE INDEX dispense_allocations_item_batch_uidx ON dispense_allocations(prescription_item_id,batch_id);
